import { describe, it, expect, vi } from 'vitest';
import { render, screen } from '@testing-library/react';
import Navigation from './app/Navigation';
import React from 'react';

// Mock next/link to simplify testing
vi.mock('next/link', () => {
  return {
    __esModule: true,
    default: ({ children, href }: { children: React.ReactNode; href: string }) => {
      return <a href={href}>{children}</a>;
    },
  };
});

describe('Navigation', () => {
  it('should verify the correct links', () => {
    render(<Navigation />);

    const blogLink = screen.getByText(/blog/i);
    expect(blogLink).toBeInTheDocument();
    expect(blogLink.closest('a')).toHaveAttribute('href', '/blog');

    const productsLink = screen.getByText(/products/i);
    expect(productsLink).toBeInTheDocument();
    expect(productsLink.closest('a')).toHaveAttribute('href', '/products');

    const supportLink = screen.getByText(/support/i);
    expect(supportLink).toBeInTheDocument();
    expect(supportLink.closest('a')).toHaveAttribute('href', '/support');
  });
});

